script:
let banner = $(root_element).find("#user-profile-banner");
let email = frappe.session.user_email;
let avatar = frappe.avatar(email);

// Load banner image from SEAL HRMS Settings
frappe.call({
    method: 'frappe.client.get_value',
    args: {
        doctype: 'SEAL HRMS Settings',
        filters: 'SEAL HRMS Settings',
        fieldname: ['ess_banner_image']
    },
    callback: function(r) {
        if (r.message && r.message.ess_banner_image) {
            banner.find(".banner img").attr("src", r.message.ess_banner_image);
        }
    }
});

// Load employee profile details
frappe.call({
    method: 'frappe.client.get_value',
    args: {
        doctype: 'Employee',
        filters: { 'user_id': frappe.session.user },
        fieldname: ['company', 'designation', 'department', 'salutation', 'first_name']
    },
    callback: function(r) {
        if (r.message) {
            let first_name = "", company = "", department = "", designation = "";

            if (r.message.first_name)
                first_name = r.message.first_name;

            if (r.message.designation)
                designation = r.message.designation;

            if (r.message.company)
                company = designation ? " - " + r.message.company : r.message.company;

            if (r.message.department)
                department = " | " + r.message.department;

            banner.find(".full-name").text("Welcome " + first_name);
            banner.find(".employee-data").html(designation + company + department);
        }
    }
});

banner.find(".email").text(email);
banner.find(".avatar").html(avatar);

style:
#user-profile-banner {
    margin: 0px 0px 0px;
}

#user-profile-banner .banner {
    width: 100%;
    height: 280px;
}

#user-profile-banner .banner img {
    object-fit: cover;
    width: 100%;
    height: inherit;
    object-position: center 50%;
    border-top-left-radius: var(--border-radius-lg);
    border-top-right-radius: var(--border-radius-lg);
}

.avatar-small {
    width: 36px;
    height: 36px;
}

.avatar {
    display: inline-block;
    vertical-align: middle;
}

.avatar-frame {
    display: inline-block;
    width: 100%;
    height: 100%;
    object-fit: cover;
    background-color: var(--avatar-frame-bg);
    background-size: cover;
    background-repeat: no-repeat;
    background-position: center center;
    border-radius: 50%;
}

.standard-image {
    display: flex;
    justify-content: center;
    align-items: center;
    font-size: 50px;
    font-weight: normal;
}

#user-profile-banner .name {
    margin-left: 200px;
    margin-top: -70px;
}

#user-profile-banner .full-name {
    font-size: x-large;
    font-weight: 500;
}

#user-profile-banner .employee-data {
    font-size: small;
    font-weight: bold;
    margin-top: 10px;
}

#user-profile-banner .email {
    font-size: small;
    font-weight: 300;
    color: var(--text-muted);
}

#user-profile-banner .avatar {
    margin-left: 20px;
    margin-top: -35px;
}

#user-profile-banner .avatar .avatar {
    width: 140px;
    height: 140px;
    border: 4px solid var(--fg-color);
    border-radius: var(--border-radius-full);
}

.ess-flow { padding: 4px 2px; }
.ess-flow__intro h4 { margin: 0 0 6px; }
.ess-flow__intro p { color: var(--text-muted); margin: 0 0 16px; max-width: 62em; }

/* Eight tiles, so they wrap into rows rather than one long rail. */
.ess-flow__rail { display: flex; align-items: stretch; flex-wrap: wrap; gap: 8px; margin-bottom: 16px; }
.ess-flow__step {
  flex: 1 1 200px; min-width: 190px; display: flex; gap: 10px;
  border: 1px solid var(--border-color); border-radius: var(--border-radius-md, 8px);
  padding: 10px 12px; background: var(--card-bg, var(--fg-color));
}
/* The icon sits where the step number sits on the flow blocks, so the two read
   as the same family even though these are areas rather than steps. */
.ess-flow__num {
  flex: 0 0 22px; height: 22px; border-radius: 50%;
  background: var(--control-bg); font-size: 13px; line-height: 1;
  display: flex; align-items: center; justify-content: center;
}
.ess-flow__body { display: flex; flex-direction: column; line-height: 1.4; }
.ess-flow__body span { color: var(--text-muted); font-size: .85em; margin-top: 2px; }

.ess-flow__aside { display: flex; flex-wrap: wrap; gap: 8px; }
.ess-flow__card {
  flex: 1 1 260px; display: flex; flex-direction: column;
  border-left: 3px solid var(--border-color); padding: 4px 12px;
}
.ess-flow__card span { color: var(--text-muted); font-size: .85em; margin-top: 2px; }

/* Tiles are links: inherit text colour, lift on hover, keyboard focusable. */
a.ess-flow__step, a.ess-flow__card {
  text-decoration: none; color: inherit;
  transition: border-color .12s, background .12s, transform .12s;
}
a.ess-flow__step:hover, a.ess-flow__card:hover {
  border-color: var(--primary, #2490ef); background: var(--control-bg); transform: translateY(-1px);
}
a.ess-flow__step:hover .ess-flow__num { background: var(--primary, #2490ef); }
a.ess-flow__step:focus-visible, a.ess-flow__card:focus-visible {
  outline: 2px solid var(--primary, #2490ef); outline-offset: 2px;
}
